# список_шортсов.md: номер, заголовок, длительность, хук, о чём, таймкоды исходника, согласование
import json, re
PL = json.load(open('planf.json'))
ABOUT = {
 's01_chetyre_dollara': 'Сколько стоила маленькая задача (смена цвета шрифта) во фреймворке и почему вначале было 10 $: спецификация всей системы на каждую задачу.',
 's02_odna_iz_sta': 'Две точки контроля человека; из 100 задач одна сделана криво, но прошла все тесты — её остановила проверка в конце.',
 's03_gitlab_bot': 'Как устроен фреймворк лектора: задача в GitLab → бот → проверки → вопросы → тестовый сервер → прод.',
 's04_eto_ne_zadacha': 'Классификация задач: саппортная/проектная → хорошо/плохо специфицированная, вопрос и «вообще не задача».',
 's05_spec_pri_ustanovke': 'Один экземпляр фреймворка на проект; режим установки со спецификацией продукта экономит токены в десятки раз; как триггерятся агенты.',
 's06_logika_chelovecheskim': 'Ошибка: в спецификации были БД и OpenAPI, но не описание логики человеческим языком — система не заметила смену логики.',
 's07_pervyi_prompt': 'Диаграмму — в SVG и в Claude: первый промпт «найди несоответствия и проблемы», ревью ИИшкой обязательно.',
 's08_otvetstvennost': 'Кто отвечает за прод: продакт-менеджер, технической ответственности нет, ревью кода человек не делает — «мы пока очень рискуем».',
 's09_openhands': 'Почему участникам прошлого потока не понравился OpenHands: black box, много токенов, мало контроля; своя система vs внешний продукт.',
 's10_bezopasnost': 'В ревьюере обязательно проверять уязвимости: взломать можно всё, вопрос сроков и бюджетов.',
 's11_vosem_chasov': 'Сколько заняла первая версия фреймворка (часов 8 с прогонами 100 задач) и почему это дешевле найма.',
 's12_chelovek_ili_ii': 'Разминка «ИИ-модель или живой разработчик»: ответы участников (не ленится, контекст шире, black box) и вывод лектора о доверии.',
 's13_testy_v_otryve': 'Вопрос участника: тесты агентов — в отрыве от реализации? Ответ: да, API-first, маленькие ревьюеры, «элефанта» не создавать.'}
AGREE = {'s12_chelovek_ili_ii': 'Марат Хасанов, Владимир Савостин (голос + имя в кадре)', 's13_testy_v_otryve': 'Виталий Кузнецов (голос + имя в кадре)'}
tc = lambda s: f'{int(s // 3600):02d}:{int(s % 3600 // 60):02d}:{int(s % 60):02d}'
fn = lambda t: re.sub(r'<[^>]+>', '', t).replace('?', '').replace('—', '-').strip()
out = ['# Шортсы — Урок 12 (24.11.2026), End-to-end SDLC, Даниил Пилипенко (SymbioWay)', '',
       'Формат 1080×1920, шапка «Разработка / SDLC», хук — фраза лектора в ноль, концовка Нэйшн. Студентов без камеры показываем экраном Zoom с подписью имени.', '']
for n, p in enumerate(PL, 1):
    s = json.load(open(p['id'] + '.spec.json'))
    hook = ' '.join(w['t'] for c in s['chunks'] if c['s'] < s['hookEnd'] - 0.05 for w in c['words'])
    t = re.sub(r'<[^>]+>', '', s['title'])
    out += [f'## {n:02d}. {t}', f'- Файл: `{n:02d} {fn(s["title"])}.mp4` · длительность **{s["dur"]:.0f} с**',
            f'- Хук: «{hook}»', f'- О чём: {ABOUT[p["id"]]}',
            f'- Исходник: ' + ', '.join(f'{tc(a)}–{tc(b)}' for a, b in sorted(p['segs'][1:])) + f' (хук {tc(p["segs"][0][0])})',
            f'- Согласовать со студентом: **{AGREE[p["id"]]}**' if p['id'] in AGREE else '- Согласование: не нужно (только лектор)', '']
open('список_шортсов.md', 'w').write('\n'.join(out)); print('\n'.join(out[:12]))
